    .string("b"): .bool(true),
    .string("c"): .string("hello"),
  ])

  let smallArray = Value.array([
    .number(1), .number(2), .number(3), .string("x"), .bool(false)
  ])

  let largeString = String(repeating: "abcdefgh", count: 2048)
  let largeBytes = Data(repeating: 0xAB, count: 64 * 1024)

  let largeArray: Value = .array((0..<10_000).map { .number($0) })

  let largeMap: Value = .object(
    (0..<5_000).reduce(into: Value.Object()) { dict, idx in
      dict[.string("k\(idx)")] = .number(idx)
    }
  )

  let taggedValue: Value = .tagged(tags: [.number(1)], value: .string("tagged"))

  let deterministicMap: Value = .object([
    .string("b"): .number(1),
    .string("a"): .number(2),
  ])

  let smallMapData = try? CBORValueWriter.write(smallMap)
  let smallArrayData = try? CBORValueWriter.write(smallArray)
  let largeArrayData = try? CBORValueWriter.write(largeArray)
  let largeMapData = try? CBORValueWriter.write(largeMap)
  let largeStringData = try? CBORValueWriter.write(.string(largeString))
  let largeBytesData = try? CBORValueWriter.write(.bytes(largeBytes))
  let taggedData = try? CBORValueWriter.write(taggedValue)

  // MARK: - Encode (Value)

  Benchmark("CBOR Encode Small Map", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let data = try? CBORValueWriter.write(smallMap)
      blackHole(data)
    }
  }

  Benchmark("CBOR Encode Small Array", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let data = try? CBORValueWriter.write(smallArray)
      blackHole(data)
    }
  }

  Benchmark("CBOR Encode Large Array", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let data = try? CBORValueWriter.write(largeArray)
      blackHole(data)
    }
  }

  Benchmark("CBOR Encode Large Map", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let data = try? CBORValueWriter.write(largeMap)
      blackHole(data)
    }
  }

  Benchmark("CBOR Encode Large String", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let data = try? CBORValueWriter.write(.string(largeString))
      blackHole(data)
    }
  }

  Benchmark("CBOR Encode Large Bytes", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let data = try? CBORValueWriter.write(.bytes(largeBytes))
      blackHole(data)
    }
  }

  Benchmark("CBOR Encode Tagged", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let data = try? CBORValueWriter.write(taggedValue)
      blackHole(data)
    }
  }

  // MARK: - Decode (Value)

  Benchmark("CBOR Decode Small Map", configuration: config) { benchmark in
    guard let smallMapData else { return }
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      var reader = CBORValueReader(data: smallMapData)
      let value = try? reader.read()
      blackHole(value)
