    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      var reader = CBORValueReader(data: taggedData)
      let value = try? reader.read()
      blackHole(value)
    }
  }

  // MARK: - Stream Writer

  Benchmark("CBOR Stream Writer Small Map", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let sink = DataSink()
      let writer = CBORStreamWriter(sink: sink)
      let events = EmitEventEncoder().encode(smallMap)
      for event in events {
        try? await writer.write(event)
      }
      try? await writer.finish()
      blackHole(sink.data)
    }
  }

  Benchmark("CBOR Stream Writer Deterministic", configuration: config) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      let sink = DataSink()
      let writer = CBORStreamWriter(sink: sink, options: .init(deterministic: true))
      let events = EmitEventEncoder().encode(deterministicMap)
      for event in events {
        try? await writer.write(event)
